const { execFile } = require('child_process');
const fs = require('fs');
const args = [
  '/data/scripts/library_collector.mjs',
  '--queue', '/data/research-alerts/research_queue.json',
  '--existing-ids', '/data/research-alerts/sheet_ids.json',
  '--seen', '/data/research-alerts/n8n_seen.json',
  '--state', '/data/research-alerts/n8n_collector_state.json',
  '--out-dir', '/data/research-alerts/incoming',
  '--max-new', '70',
  '--topics-per-run', '12',
  '--per-source', '8',
];
const started = Date.now();

function batchWrittenThisRun() {
  const dir = '/data/research-alerts/incoming';
  let best = '';
  let bestMtime = 0;
  for (const name of fs.readdirSync(dir)) {
    if (name.indexOf('n8n-append-') !== 0 || name.slice(-5) !== '.json') continue;
    const full = dir + '/' + name;
    const mtime = fs.statSync(full).mtimeMs;
    if (mtime + 2000 >= started && mtime >= bestMtime) {
      best = full;
      bestMtime = mtime;
    }
  }
  return best;
}

const executed = await new Promise((resolve) => {
  execFile('/usr/local/bin/node', args, {
    encoding: 'utf8',
    timeout: 540000,
    maxBuffer: 12 * 1024 * 1024,
  }, (error, stdout, stderr) => {
    resolve({
      output: stdout ? String(stdout) : '',
      errMsg: error ? String(error.message || error) : '',
      stderr: stderr ? String(stderr) : '',
    });
  });
});

let parsed = null;
try { parsed = JSON.parse(executed.output); } catch (e) { parsed = null; }
if (parsed && parsed.ok) {
  return [{ json: parsed }];
}
const latest = batchWrittenThisRun();
if (latest) {
  const payload = JSON.parse(fs.readFileSync(latest, 'utf8'));
  return [{ json: { ok: true, recovered: true, warning: executed.errMsg, json: latest, count: payload.new_count } }];
}
throw new Error('collector failed: ' + executed.errMsg + '\n' + executed.stderr + '\n' + executed.output);
